def weights_independent(model,name):
    result=[]
    for prefix in ['conv1','conv2','head']:
        w=model[prefix+'_weight'].astype(float);out=np.empty_like(w)
        for ch,row in enumerate(w):
            flat=row.ravel();c=(max(flat)+min(flat))/2;r=(max(flat)-min(flat))/2
            if '_minmax' in name:
                levels=2**int(name.split('_INT')[1].split('_')[0])-1;q=(flat-c)/r/2+.5 if r else np.full_like(flat,.5);v=(c-r)+2*r*np.rint(np.minimum(1,np.maximum(0,q))*levels)/levels
            elif '_symmetric' in name:
                limit=2**(int(name.split('_INT')[1].split('_')[0])-1)-1;scale=max(abs(flat))/limit;v=np.round(flat/scale).clip(-limit,limit)*scale if scale else np.zeros_like(flat)
            elif name=='ACT8_nominal_programmed_mean':
                q=(flat-c)/r/2+.5 if r else np.full_like(flat,.5);e=1/(1+np.exp(8));q=np.clip(q,e,1-e);code=np.round((np.log(q/(1-q))/2+4)*255/8).astype(np.uint8);f=(-4+code.astype(float)*8/255).astype(np.float32).astype(float);prob=1/(1+np.exp(-2*f));np.testing.assert_allclose(prob,np.exp(-np.logaddexp(0,-2*f)),rtol=1e-14,atol=1e-16);v=(c-r)+2*r/(1+np.exp(-2*f))
            else:v=flat
            out[ch]=v.reshape(row.shape)
        result.append(out)
    return result
def metric(z,y):
    top=z.max(1);shift=z-top[:,None];loss=np.log(np.exp(shift).sum(1))-shift[np.arange(len(y)),y];return np.array([np.count_nonzero(z.argmax(1)==y)/len(y),loss.mean()])
